  p = fmaf(p, tp, -1.13520398f * 64.f * L); p = fmaf(p, tp, 0.27886807f * 32.f * L);
  p = fmaf(p, tp, -0.18628806f * 16.f * L); p = fmaf(p, tp, 0.09678418f * 8.f * L);
  p = fmaf(p, tp, 0.37409196f * 4.f * L); p = fmaf(p, tp, 1.00002368f * 2.f * L);
  p = fmaf(p, tp, -1.26551223f * L);
