template <bool G, int GM>
__device__ __forceinline__ void run_batch(const char* base, const float2* sb, int tb, int t1, int ts, int TS, int kc, int LD,
                                          int K4, const float* uu, const float* cc, float* acc, float invC, float ln_eps, u64 pol) {
  u4 v[8]; float2 st[8];
#pragma unroll
  for (int j = 0; j < 8; ++j) {
    const int tt = tb + ts + j * TS;
    if (!G || tt < t1) { v[j] = ld_na(base + ((size_t)tt * LD + kc * 8) * 2); st[j] = sb[tt]; }
  }
