  for (int j = 0; j < 8; ++j) {
    const int tt = tb + ts + j * TS;
    if (!G || tt < t1) {
      const float mean = st[j].x * invC;
      const float var = fmaxf(st[j].y * invC - mean * mean, 0.f);
      const float rs = rsqrtf(var + ln_eps);
      const float rm = rs * mean;
