        const float h1 = gel<GM>(fmaf(rs, f1, fmaf(-rm, uu[2 * q + 1], cc[2 * q + 1])));
        acc[2 * q] = fmaf(h0, h0, acc[2 * q]);
        acc[2 * q + 1] = fmaf(h1, h1, acc[2 * q + 1]);
        o[q] = pk(h0, h1);
