__device__ __forceinline__ void k2body(char* Y, const float* uvec, const float* cvec, const float2* stats, float* sumsq, int HW, int C,
                                       int LD, int TR, float ln_eps, int hint) {
  __shared__ float red[2048];
  const int V = C >> 1, K4 = 4 * C;
  const int tid = threadIdx.x, kc = tid % V, ts = tid / V, TS = blockDim.x / V;
  const int b = blockIdx.y, t0 = blockIdx.x * TR, t1 = min(t0 + TR, HW);
