  }
  for (; tb < t1; tb += batch)
    run_batch<true, GM>(base, sb, tb, t1, ts, TS, kc, LD, K4, uu, cc, acc, invC, ln_eps, pol);
  if (TS > 1 && ts > 0) {
#pragma unroll
    for (int i = 0; i < 8; ++i) red[(ts - 1) * K4 + kc * 8 + i] = acc[i];
  }
  __syncthreads();
