__device__ __forceinline__ void st_pol(void* p, u4 v, u64 pol) {
  asm volatile("st.global.L2::cache_hint.v4.u32 [%0], {%1, %2, %3, %4}, %5;" :: "l"(p), "r"(v.x), "r"(v.y), "r"(v.z), "r"(v.w), "l"(pol) : "memory"); }
__device__ __forceinline__ void unp(unsigned v, float& lo, float& hi) {
  asm("{ .reg .b16 l, h; mov.b32 {l, h}, %2; cvt.f32.f16 %0, l; cvt.f32.f16 %1, h; }" : "=f"(lo), "=f"(hi) : "r"(v)); }
__device__ __forceinline__ unsigned pk(float x, float y) { unsigned d; asm("cvt.rn.f16x2.f32 %0, %2, %1;" : "=r"(d) : "f"(x), "f"(y)); return d; }
__device__ __forceinline__ void mbar_wait(u64* bar, unsigned par) {
  asm volatile("{ .reg .pred p; W: mbarrier.try_wait.parity.shared::cta.b64 p, [%0], %1; @!p bra W; }" :: "r"(su32(bar)), "r"(par) : "memory"); }
__device__ __forceinline__ void expect_tx(u64* bar, unsigned bytes) {
  asm volatile("mbarrier.arrive.expect_tx.shared::cta.b64 _, [%0], %1;" :: "r"(su32(bar)), "r"(bytes) : "memory"); }
__device__ __forceinline__ void bulk_g2s(void* dst, const void* src, unsigned bytes, u64* bar) {
  asm volatile("cp.async.bulk.shared::cluster.global.mbarrier::complete_tx::bytes [%0], [%1], %2, [%3];" :: "r"(su32(dst)), "l"(src), "r"(bytes), "r"(su32(bar)) : "memory"); }

template <int GM>
__device__ __forceinline__ void ringbody(char* Y, const float* uvec, const float* cvec, const float2* stats, float* sumsq, int HW, int C,
                                         int LD, int TR, int M, int nch, float ln_eps, int hint, int NS) {
  extern __shared__ __align__(128) unsigned char smem[];
  __shared__ __align__(8) u64 bars[8];
  const int V = C >> 1, K4 = 4 * C, RB = 8 * C;
  const int tid = threadIdx.x, lane = tid & 31, warp = tid >> 5, kc = tid % V, ts = tid / V, TS = blockDim.x / V;
  const int TT = 4 * TS, stageB = TT * RB;
  const int b = blockIdx.y, t0 = blockIdx.x * TR, t1 = min(t0 + TR, HW), ntok = t1 - t0;
  const int nst = (ntok + TT - 1) / TT;
  float2* ms = reinterpret_cast<float2*>(smem + NS * stageB);
  const char* gbase = Y + (size_t)b * HW * LD * 2;
  if (tid == 0) {
    for (int s = 0; s < NS; ++s) asm volatile("mbarrier.init.shared::cta.b64 [%0], 1;" :: "r"(su32(&bars[s])));
    asm volatile("fence.mbarrier_init.release.cluster;");
  }
  __syncthreads();
  if (warp == 0) {
    for (int it = 0; it < min(NS, nst); ++it) {
      const int s = it % NS, first = it * TT, rows = min(TT, ntok - first);
      if (lane == 0) expect_tx(&bars[s], rows * RB);
      __syncwarp();
      for (int r = lane; r < rows; r += 32) bulk_g2s(smem + s * stageB + r * RB, gbase + (size_t)(t0 + first + r) * LD * 2, RB, &bars[s]);
    }
  }
  u64 pol;
  if (hint == 1) asm volatile("createpolicy.fractional.L2::evict_last.b64 %0, 1.0;" : "=l"(pol));
  else if (hint == 2) asm volatile("createpolicy.fractional.L2::evict_first.b64 %0, 1.0;" : "=l"(pol));
  else asm volatile("createpolicy.fractional.L2::evict_normal.b64 %0, 1.0;" : "=l"(pol));
  float uu[8], cc[8];
  for (int i = 0; i < 8; ++i) { uu[i] = uvec[kc * 8 + i]; cc[i] = cvec[kc * 8 + i]; }
  const float invC = 1.f / (float)C;
  for (int tl = tid; tl < ntok; tl += blockDim.x) {
    float s = 0.f, q = 0.f;
    const float2* sb = stats + (size_t)b * HW + t0 + tl;
    for (int ch = 0; ch < nch; ++ch) { const float2 v = sb[(size_t)ch * M]; s += v.x; q += v.y; }
    const float mean = s * invC;
    const float var = fmaxf(q * invC - mean * mean, 0.f);
    const float rs = rsqrtf(var + ln_eps);
    ms[tl] = make_float2(rs, rs * mean);
  }
  __syncthreads();
  float acc[8];
#pragma unroll
  for (int i = 0; i < 8; ++i) acc[i] = 0.f;
  for (int it = 0; it < nst; ++it) {
    const int s = it % NS;
    mbar_wait(&bars[s], (unsigned)((it / NS) & 1));
    const uint4* sp = reinterpret_cast<const uint4*>(smem + s * stageB) + kc;
    uint4 v[4];
#pragma unroll
    for (int jj = 0; jj < 4; ++jj) v[jj] = sp[(ts + jj * TS) * V];
#pragma unroll
    for (int jj = 0; jj < 4; ++jj) {
      const int tl = it * TT + ts + jj * TS;
      if (tl < ntok) {
        const float2 m = ms[tl];
        unsigned in[4] = {v[jj].x, v[jj].y, v[jj].z, v[jj].w};
        unsigned o[4];
#pragma unroll
        for (int q = 0; q < 4; ++q) {
          float f0, f1; unp(in[q], f0, f1);
          const float h0 = gel<GM>(fmaf(m.x, f0, fmaf(-m.y, uu[2 * q], cc[2 * q])));
          const float h1 = gel<GM>(fmaf(m.x, f1, fmaf(-m.y, uu[2 * q + 1], cc[2 * q + 1])));
          acc[2 * q] = fmaf(h0, h0, acc[2 * q]);
          acc[2 * q + 1] = fmaf(h1, h1, acc[2 * q + 1]);
          o[q] = pk(h0, h1);
        }
        char* rowp = const_cast<char*>(gbase) + (size_t)(t0 + tl) * LD * 2;
        u4 ov; ov.x = o[0]; ov.y = o[1]; ov.z = o[2]; ov.w = o[3];
        st_pol(rowp + kc * 16, ov, pol);
        if (kc == 0) { u4 one; one.x = 0x3C003C00u; one.y = 0; one.z = 0; one.w = 0; st_pol(rowp + K4 * 2, one, pol); }
      }
    }
    __syncthreads();
    if (warp == 0 && it + NS < nst) {
      const int first = (it + NS) * TT, rows = min(TT, ntok - first);
      if (lane == 0) expect_tx(&bars[s], rows * RB);
      __syncwarp();
      for (int r = lane; r < rows; r += 32) bulk_g2s(smem + s * stageB + r * RB, gbase + (size_t)(t0 + first + r) * LD * 2, RB, &bars[s]);
    }
  }
  float* red = reinterpret_cast<float*>(smem);
  if (TS > 1 && ts > 0) {
#pragma unroll
    for (int i = 0; i < 8; ++i) red[(ts - 1) * K4 + kc * 8 + i] = acc[i];
  }
  __syncthreads();
  if (ts == 0) {
    for (int q = 1; q < TS; ++q) {
#pragma unroll
      for (int i = 0; i < 8; ++i) acc[i] += red[(q - 1) * K4 + kc * 8 + i];
    }
    float* dst = sumsq + ((size_t)b * 4 + (blockIdx.x % 4)) * K4 + kc * 8;
#pragma unroll
    for (int i = 0; i < 8; ++i) atomicAdd(dst + i, acc[i]);
  }
}
